[Source 1: oracle-hospitality-property-workflows.postman_collection.json — Property Interfaces - Room Equipment]
Workflow: Property Interfaces - Room Equipment
Steps: 9

Step 1: Change the Room Maid Status to Inspected
  PUT /hsk/v1/hotels/{{HotelId}}/rooms/status
  Body:
{
    "roomList": [
        {
            "roomId": "103"
        }
    ],
    "housekeepingStatus": "Occupied",
    "housekeepingRoomStatus": "Inspected"
}

Step 2: Change the Room Maid Status to Clean
  PUT /hsk/v1/hotels/{{HotelId}}/rooms/status
  Body:
{
    "roomList": [
        {
            "roomId": "103"
        }
    ],
    "housekeepingStatus": "Occupied",
    "housekeepingRoomStatus": "Clean"
}

Step 3: Change the Room Maid Status to Dirty
  PUT /hsk/v1/hotels/{{HotelId}}/rooms/status
  Body:
{
    "roomList": [
        {
            "roomId": "103"
        }
    ],
    "housekeepingStatus": "Occupied",
    "housekeepingRoomStatus": "Dirty"
}

Step 4: Change the Room Maid Status to Pickup
  PUT /hsk/v1/hotels/{{HotelId}}/rooms/status
  Body:
{
    "roomList": [
        {
            "roomId": "103"
        }
    ],
    "housekeepingStatus": "Occupied",
    "housekeepingRoomStatus": "Pickup"
}

Step 5: Set the Guest Service Status to DND - active
  PUT /hsk/v1/hotels/{{HotelId}}/serviceRequests
  Body:
{
    "criteria": {
        "hotelId": "{{HotelId}}",
        "roomList": [
            "104"
        ],
        "status": "DoNotDisturb"
    }
}

Step 6: Set the Guest Service Status to MUR - active
  PUT /hsk/v1/hotels/{{HotelId}}/serviceRequests
  Body:
{
    "criteria": {
        "hotelId": "{{HotelId}}",
        "roomList": [
            "104"
        ],
        "status": "MakeUpRoom"
    }
}

Step 7: Set the Guest Service Status to DND or MUR - off
  PUT /hsk/v1/hotels/{{HotelId}}/serviceRequests
  Body:
{
    "criteria": {
        "hotelId": "{{HotelId}}",
        "roomList": [
            "104"
        ],
        "status": "NoStatusSelected"
    }
}

Step 8: Post a Guest Message - New Voicemail
  POST /rsv/v1/hotels/{{HotelId}}/reservations/{{ReservationId}}/guestMessages
  Body:
{
    "hotelId": "{{HotelId}}",
    "reservationIdList": {
        "type": "Reservation",
        "id": "{{ReservationId}}"
    },
    "guestMessages": [
        {
            "message": {
                "messageText": "You have new Voice Mail. Please check your Phone.",
                "messageDate": "2021-12-16 15:11:31.0",
                "typeOfMessage": "Tm",
                "recipient": "",
                "operator": "PBX"
            },
            "delivery": {
                "deliveryStatus": "Nr",
                "textMessageSentBy": "PBX"
            }
        }
    ]
}

Step 9: Update Guest Message - Voicemail Off - delivered
  PUT /rsv/v1/hotels/{{HotelId}}/reservations/{{ReservationId}}/guestMessages/30040
  Body:
{
   "hotelId":"{{HotelId}}",
   "guestMessages":[
      {
         "message":{
            "messageText":"You have new Voice Mail. Please check your Phone.",
            "messageDate":"2021-12-16 15:11:31.0",
            "typeOfMessage":"Tm",
            "recipient":""
         },
         "delivery":{
            "deliveryStatus":"Mr",
            "deliveryDate": "2021-12-16 15:31:31.0",
            "deliveredBy": "PBX"
         }
      }
   ]
}


