Step 2: Create Room Key - property must have an active doorlocking integration
  POST /fof/v1/hotels/{{HotelId}}/reservations/reservationId/roomKeys
  Body:
{
    "reservationIdList": [
        {
            "type": "Reservation",
            "id": "{{ReservationId}}"
        }
    ],
    "keyOptions": "GAR,RFT",
    "keyValidityStart": "2021-22-25 12:00:00.0",
    "noOfKeys": "1",
    "encoderTerminal": "APIRQ",
    "encoderId": {
        "id": "0"
    },
    "resort": "{{HotelId}}",
    "keyType": "New",
    "keyValidityEnd": "2021-11-26 13:00:00.0"
}


