[Source 2: oracle-hospitality-property-workflows.postman_collection.json — Create a Room Maintenance Request]
Workflow: Create a Room Maintenance Request
Steps: 6

Step 1: Create a new Room Maintenance Request
  POST /hsk/v1/hotels/{{HotelId}}/rooms/maintenanceCodes/{{MaintenanceCode}}
  Body:
{
    "criteria": {
        "roomIds": [
            "101"
        ],
        "hotelId": "{{HotelId}}",
        "maintenanceCode": "AIRCON",
        "remarks": "AC Repair"
    }
}

Step 2: Update an existing Room Maintenance Request
  PUT /hsk/v1/hotels/{{HotelId}}/rooms/{{RoomId}}/maintenances/{{MaintenanceId}}
  Body:
{
    "criteria": {
        "maintenanceId": {
            "type": "RoomMaintenanceId",
            "id": "5060"
        },
        "roomId": "101",
        "hotelId": "{{HotelId}}",
        "maintenanceCode": "AIRCON",
        "remarks": "AC Repair - update"
    }
}

Step 3: Resolve  a Room Maintenance Request
  PUT /hsk/v1/hotels/{{HotelId}}/maintenances/{{MaintenanceId}}/resolve
  Body:
{
    "criteria": {
        "maintenanceId": {
            "type": "RoomMaintenanceId",
            "id": "5060"
        },
        "hotelId": "{{HotelId}}"
    }
}

Step 4: unresolve a Room Maintenance Request
  PUT /hsk/v1/hotels/{{HotelId}}/maintenances/{{MaintenanceId}}/unResolve
  Body:
{
    "criteria": {
        "maintenanceId": {
            "type": "RoomMaintenanceId",
            "id": "{{MaintenanceId}}"
        },
        "hotelId": "{{HotelId}}"
    }
}

Step 5: Delete a Room Maintenance Request
  DELETE /hsk/v1/hotels/{{HotelId}}/maintenances/{{MaintenanceId}}

Step 6: Find all existing Room Maintenance Requests
  GET /hsk/v1/hotels/{{HotelId}}/rooms/maintenances
  Query: roomMaintenanceStatus=All


